#!/usr/bin/env python3
"""Targeted compile check for the CVE-2018-5953 candidate.

Extracts the patched swiotlb_print_info() from lib/swiotlb.c (cwd = checkout)
and compiles a stub translation unit with gcc-10 -fsyntax-only -Wall -Wformat=2.
This checks real C syntax and printf-format/argument agreement for the changed
code even though the kernel cannot be configured/built (no make, no .config).

Exit 0 when the extraction and gcc syntax check succeed.
"""
import re
import subprocess
import sys
import tempfile
from pathlib import Path

GCC = "/usr/bin/gcc-10"
if not Path(GCC).exists():
    print("SKIP gcc-10 not available")
    sys.exit(0)

src = Path("lib/swiotlb.c").read_text(encoding="utf-8", errors="replace")


def balanced_function(text, signature):
    start = text.find(signature)
    if start < 0:
        return None
    brace = text.find("{", start)
    if brace < 0:
        return None
    depth = 0
    for i in range(brace, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                return text[start:i + 1]
    return None


func = balanced_function(src, "void swiotlb_print_info(void)")
if not func:
    print("FAIL could not extract swiotlb_print_info")
    sys.exit(1)

tu = r"""
typedef unsigned long long phys_addr_t;
typedef int bool;
#define false 0
#define true 1
#define IO_TLB_SHIFT 11

extern unsigned long io_tlb_nslabs;
extern phys_addr_t io_tlb_start;
extern phys_addr_t io_tlb_end;
extern bool no_iotlb_memory;

extern int check_printf(const char *fmt, ...)
    __attribute__((format(printf, 1, 2)));
#define pr_warn(fmt, ...) check_printf(fmt, ##__VA_ARGS__)
#define pr_info(fmt, ...) check_printf(fmt, ##__VA_ARGS__)

""" + func + r"""

void check_other_reports(void)
{
	unsigned int order = 3;
	volatile unsigned long mb;
	pr_warn("Cannot allocate buffer");
	mb = ((unsigned long)(1UL << 12) << order) >> 20;
	pr_warn("only able to allocate %ld MB\n", mb);
}
"""

with tempfile.TemporaryDirectory(prefix="swiotlb-cc-") as td:
    tu_path = Path(td) / "stub.c"
    tu_path.write_text(tu, encoding="utf-8")
    proc = subprocess.run(
        [GCC, "-fsyntax-only", "-std=gnu89", "-Wall", "-Wformat=2",
         str(tu_path)],
        capture_output=True, text=True,
    )
    print(proc.stdout, end="")
    print(proc.stderr, end="")
    if proc.returncode != 0:
        print("FAIL gcc-10 syntax/format check exit=%d" % proc.returncode)
        sys.exit(1)
    print("PASS gcc-10 syntax and format check of swiotlb_print_info + reports")
    sys.exit(0)

